function asArray(item) {
  const json = item.json;
  if (Array.isArray(json)) return json;
  if (json && json.data && Array.isArray(json.data.scheduledTouches)) return json.data.scheduledTouches;
  if (json && Array.isArray(json.scheduledTouches)) return json.scheduledTouches;
  return [];
}

const now = new Date();
const overdue = $input.all().flatMap(asArray)
  .filter((t) => !t.disposition && new Date(t.scheduledAt) < now);

return overdue.map((t) => ({ json: t }));
